  1	class BTreeNode {
  2	    private final int[] keys;
  3	    private final int minimumDegree;
  4	    private final BTreeNode[] children;
  5	    private int keyCount;
  6	    private final boolean leaf;
  7	
  8	    public BTreeNode(int minimumDegree, boolean leaf) {
  9	        this.keys = new int[2 * minimumDegree - 1];
 10	        this.minimumDegree = minimumDegree;
 11	        this.children = new BTreeNode[2 * minimumDegree];
 12	        this.keyCount = 0;
 13	        this.leaf = leaf;
 14	    }
 15	
 16	    static BTreeNode leafWithSingleKey(int minimumDegree, int key) {
 17	        BTreeNode node = new BTreeNode(minimumDegree, true);
 18	        node.initializeWithSingleKey(key);
 19	        return node;
 20	    }
 21	
 22	    static BTreeNode internalRootWithFirstChild(int minimumDegree, BTreeNode firstChild) {
 23	        BTreeNode node = new BTreeNode(minimumDegree, false);
 24	        node.setChild(0, firstChild);
 25	        return node;
 26	    }
 27	
 28	    private void initializeWithSingleKey(int key) {
 29	        keys[0] = key;
 30	        keyCount = 1;
 31	    }
 32	
 33	    private void setChild(int index, BTreeNode child) {
 34	        children[index] = child;
 35	    }
 36	
 37	    boolean isFull() {
 38	        return keyCount == maximumKeyCount();
 39	    }
 40	
 41	    private int maximumKeyCount() {
 42	        return 2 * minimumDegree - 1;
 43	    }
 44	
 45	    private int insertionPosition(int key) {
 46	        int index = keyCount - 1;
 47	        while (index >= 0 && keys[index] > key) {
 48	            index--;
 49	        }
 50	        return index + 1;
 51	    }
 52	
 53	    void insertNonFull(int key) {
 54	        if (leaf) {
 55	            insertIntoLeaf(key);
 56	            return;
 57	        }
 58	
 59	        insertIntoChild(key);
 60	    }
 61	
 62	    private void insertIntoLeaf(int key) {
 63	        insertKeyAt(insertionPosition(key), key);
 64	    }
 65	
 66	    private void insertIntoChild(int key) {
 67	        int childIndex = insertionPosition(key);
 68	        childIndex = prepareChildForInsert(childIndex, key);
 69	        children[childIndex].insertNonFull(key);
 70	    }
 71	
 72	    private int prepareChildForInsert(int childIndex, int key) {
 73	        if (!children[childIndex].isFull()) {
 74	            return childIndex;
 75	        }
 76	
 77	        splitChild(childIndex, children[childIndex]);
 78	        return shouldInsertIntoRightChild(childIndex, key) ? childIndex + 1 : childIndex;
 79	    }
 80	
 81	    void splitChild(int childIndex, BTreeNode child) {
 82	        BTreeNode rightSibling = createRightSibling(child);
 83	        int medianKey = medianKey(child);
 84	        trimToLeftHalf(child);
 85	        insertChildAt(childIndex + 1, rightSibling);
 86	        insertKeyAt(childIndex, medianKey);
 87	    }
 88	
 89	    private BTreeNode createRightSibling(BTreeNode node) {
 90	        BTreeNode sibling = new BTreeNode(node.minimumDegree, node.leaf);
 91	        sibling.keyCount = splitKeyCount(node);
 92	        copyRightHalfKeys(node, sibling);
 93	        if (!node.leaf) {
 94	            copyRightHalfChildren(node, sibling);
 95	        }
 96	        return sibling;
 97	    }
 98	
 99	    private int splitKeyCount(BTreeNode node) {
100	        return node.minimumDegree - 1;
101	    }
102	
103	    private void copyRightHalfKeys(BTreeNode source, BTreeNode target) {
104	        System.arraycopy(source.keys, source.minimumDegree, target.keys, 0, splitKeyCount(source));
105	    }
106	
107	    private void copyRightHalfChildren(BTreeNode source, BTreeNode target) {
108	        System.arraycopy(source.children, source.minimumDegree, target.children, 0, source.minimumDegree);
109	    }
110	
111	    private int medianKey(BTreeNode node) {
112	        return node.keys[node.minimumDegree - 1];
113	    }
114	
115	    private void trimToLeftHalf(BTreeNode node) {
116	        node.keyCount = splitKeyCount(node);
117	    }
118	
119	    private void insertChildAt(int index, BTreeNode child) {
120	        shiftChildrenRight(index);
121	        children[index] = child;
122	    }
123	
124	    private void insertKeyAt(int index, int key) {
125	        shiftKeysRight(index);
126	        keys[index] = key;
127	        keyCount++;
128	    }
129	
130	    private void shiftKeysRight(int fromIndex) {
131	        System.arraycopy(keys, fromIndex, keys, fromIndex + 1, keyCount - fromIndex);
132	    }
133	
134	    private void shiftChildrenRight(int fromIndex) {
135	        System.arraycopy(children, fromIndex, children, fromIndex + 1, keyCount - fromIndex + 1);
136	    }
137	
138	    void traverse() {
139	        StringBuilder traversal = new StringBuilder();
140	        appendTraversal(traversal);
141	        System.out.print(traversal);
142	    }
143	
144	    void appendTraversal(StringBuilder traversal) {
145	        for (int index = 0; index < keyCount; index++) {
146	            if (!leaf) {
147	                children[index].appendTraversal(traversal);
148	            }
149	            traversal.append(' ').append(keys[index]);
150	        }
151	        if (!leaf) {
152	            children[keyCount].appendTraversal(traversal);
153	        }
154	    }
155	
156	    BTreeNode search(int key) {
157	        int index = searchPosition(key);
158	        if (hasKeyAt(index, key)) {
159	            return this;
160	        }
161	        if (leaf) {
162	            return null;
163	        }
164	        return children[index].search(key);
165	    }
166	
167	    private boolean hasKeyAt(int index, int key) {
168	        return index < keyCount && key == keys[index];
169	    }
170	
171	    private int searchPosition(int key) {
172	        int index = 0;
173	        while (index < keyCount && key > keys[index]) {
174	            index++;
175	        }
176	        return index;
177	    }
178	
179	    void insertAfterRootSplit(int key) {
180	        int childIndex = shouldInsertIntoRightChild(0, key) ? 1 : 0;
181	        children[childIndex].insertNonFull(key);
182	    }
183	
184	    private boolean shouldInsertIntoRightChild(int childIndex, int key) {
185	        return keys[childIndex] < key;
186	    }
187	}
