189	class BTree {
190	    private BTreeNode root;
191	    private final int minimumDegree;
192	
193	    public BTree(int minimumDegree) {
194	        this.root = null;
195	        this.minimumDegree = minimumDegree;
196	    }
197	
198	    static BTree of(int minimumDegree, int... keys) {
199	        BTree tree = new BTree(minimumDegree);
200	        tree.insertAll(keys);
201	        return tree;
202	    }
203	
204	    String traversal() {
205	        StringBuilder traversal = new StringBuilder();
206	        if (!isEmpty()) {
207	            root.appendTraversal(traversal);
208	        }
209	        return traversal.toString();
210	    }
211	
212	    void traverse() {
213	        System.out.print(traversal());
214	    }
215	
216	    BTreeNode search(int key) {
217	        return isEmpty() ? null : root.search(key);
218	    }
219	
220	    boolean contains(int key) {
221	        return search(key) != null;
222	    }
223	
224	    void insertAll(int... keys) {
225	        for (int key : keys) {
226	            insert(key);
227	        }
228	    }
229	
230	    void insert(int key) {
231	        if (isEmpty()) {
232	            createRoot(key);
233	            return;
234	        }
235	
236	        if (root.isFull()) {
237	            splitRootAndInsert(key);
238	            return;
239	        }
240	
241	        root.insertNonFull(key);
242	    }
243	
244	    private boolean isEmpty() {
245	        return root == null;
246	    }
247	
248	    private void createRoot(int key) {
249	        root = BTreeNode.leafWithSingleKey(minimumDegree, key);
250	    }
251	
252	    private void splitRootAndInsert(int key) {
253	        BTreeNode newRoot = splitRoot();
254	        newRoot.insertAfterRootSplit(key);
255	        root = newRoot;
256	    }
257	
258	    private BTreeNode splitRoot() {
259	        BTreeNode newRoot = BTreeNode.internalRootWithFirstChild(minimumDegree, root);
260	        newRoot.splitChild(0, root);
261	        return newRoot;
262	    }
263	}
